steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        users(includeInactive: false) {
          nodes {
            id
            name
            email
          }
        }
        teams {
          nodes {
            id
            name
            key
            projects {
              nodes {
                id
                name
                key
              }
            }
          }
        }
      }
    "
  }'
